CSVMasterdataLineCreator = {
  init: async function (app, container) {
    app = app || session.app;
    container = container || $(".component[name=CSVMasterdataLineCreator]");
    var validator = container.kendoValidator().data("kendoValidator");
    $("[name=create]", container).on("click", e => CSVMasterdataLineCreator.createMasterdataLine(e, app, container));
  },

  createMasterdataLine: async function (e, app,  container) {
    e.preventDefault();
    var data = $("[name=csvData]", container).val();
    await api.sendRaw("POST", "DMS/Data/Masterdata/Received/" + app.Config.B2B.SourceSystem + "Masterdata" + (new Date()).toISOString() + ".csv", data, "text/plain").then(async () => {
      notification.success("[resource_displayname[addedtodms]]");
    }).catch((err) => error(err));
  }
}
